#!/usr/bin/env python3
from pathlib import Path
p=Path('scripts/p02-v2529-formal-gate.sh')
s=p.read_text(encoding='utf-8')
old='''setup_site http://127.0.0.1:18290 "$TMP/old.cookie" "P02-V2529-Old-${GITHUB_RUN_ID}!" "$TMP/old-setup.html"\nphp -r \'require $argv[1]."/app/bootstrap.php";$d=vftb_db();$n=gmdate("c");$q=$d->prepare("INSERT INTO text_categories(parent_id,name,description,icon,sort_order,created_at,updated_at) VALUES(NULL,?,?,?,?,?,?)");$q->execute(["Pre V2529","fixture","folder",100,$n,$n]);$c=(int)$d->lastInsertId();$q=$d->prepare("INSERT INTO text_items(category_id,title,description,content,content_mode,content_format,primary_action,status,aliases,tags,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");$q->execute([$c,"P02_V2529_SENTINEL","fixture","preserve common baseline release","quick","plain","copy","active","[]","[]",$n,$n]);\' "$OLDSITE"\ncp "$OUTA/repair-v2.5.29.php" "$OLDSITE/repair-v2.5.29.php"\nBASEURL=http://127.0.0.1:18290\ncode=$(curl -sS -o /dev/null -w '%{http_code}' -b "$TMP/old.cookie" -c "$TMP/old.cookie" "$BASEURL/repair-v2.5.29.php"); [[ "$code" == 303 ]]\ncurl -fsS -b "$TMP/old.cookie" -c "$TMP/old.cookie" "$BASEURL/repair-v2.5.29.php" > "$TMP/repair-form.html"\nRCSRF=$(python3 - "$TMP/repair-form.html" <<'PY'\nimport html,re,sys\ns=open(sys.argv[1],encoding='utf-8').read(); m=re.search(r'name="csrf" value="([^\"]+)"',s)\nif not m: raise SystemExit('repair csrf missing')\nprint(html.unescape(m.group(1)))\nPY\n)\ncurl -fsS -b "$TMP/old.cookie" -c "$TMP/old.cookie" -H "Origin: $BASEURL" --data-urlencode action=upgrade --data-urlencode "csrf=$RCSRF" "$BASEURL/repair-v2.5.29.php" > "$TMP/repair-result.html"\ngrep -q '升级完成' "$TMP/repair-result.html"'''
new='''OLDPASS="P02-V2529-Old-${GITHUB_RUN_ID}!"\nsetup_site http://127.0.0.1:18290 "$TMP/old.cookie" "$OLDPASS" "$TMP/old-setup.html"\nphp -r \'require $argv[1]."/app/bootstrap.php";$d=vftb_db();$n=gmdate("c");$q=$d->prepare("INSERT INTO text_categories(parent_id,name,description,icon,sort_order,created_at,updated_at) VALUES(NULL,?,?,?,?,?,?)");$q->execute(["Pre V2529","fixture","folder",100,$n,$n]);$c=(int)$d->lastInsertId();$q=$d->prepare("INSERT INTO text_items(category_id,title,description,content,content_mode,content_format,primary_action,status,aliases,tags,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");$q->execute([$c,"P02_V2529_SENTINEL","fixture","preserve common baseline release","quick","plain","copy","active","[]","[]",$n,$n]);\' "$OLDSITE"\ncp "$OUTA/repair-v2.5.29.php" "$OLDSITE/repair-v2.5.29.php"\nBASEURL=http://127.0.0.1:18290\ncode=$(curl -sS -D "$TMP/repair-head.txt" -o "$TMP/repair-form.html" -w '%{http_code}' -b "$TMP/old.cookie" -c "$TMP/old.cookie" "$BASEURL/repair-v2.5.29.php")\nif [[ "$code" == 303 ]]; then\n  LOC=$(awk 'BEGIN{IGNORECASE=1}/^Location:/{gsub("\\r","");print $2;exit}' "$TMP/repair-head.txt")\n  test -n "$LOC"\n  curl -fsS -b "$TMP/old.cookie" -c "$TMP/old.cookie" "$BASEURL${LOC}" > "$TMP/repair-form.html"\nelif [[ "$code" != 200 ]]; then\n  echo "Unexpected repair GET status: $code" >&2; cat "$TMP/repair-form.html" >&2; exit 1\nfi\nif grep -q 'name="action" value="login"' "$TMP/repair-form.html"; then\n  curl -fsS -b "$TMP/old.cookie" -c "$TMP/old.cookie" -H "Origin: $BASEURL" --data-urlencode action=login --data-urlencode "password=$OLDPASS" "$BASEURL/repair-v2.5.29.php?vf_same_site_bridge=1" > "$TMP/repair-form.html"\nfi\ngrep -q 'name="action" value="upgrade"' "$TMP/repair-form.html"\nRCSRF=$(python3 - "$TMP/repair-form.html" <<'PY'\nimport html,re,sys\ns=open(sys.argv[1],encoding='utf-8').read(); m=re.search(r'name="csrf" value="([^\"]+)"',s)\nif not m: raise SystemExit('repair csrf missing')\nprint(html.unescape(m.group(1)))\nPY\n)\ncurl -fsS -b "$TMP/old.cookie" -c "$TMP/old.cookie" -H "Origin: $BASEURL" --data-urlencode action=upgrade --data-urlencode "csrf=$RCSRF" "$BASEURL/repair-v2.5.29.php?vf_same_site_bridge=1" > "$TMP/repair-result.html"\ngrep -q '升级完成' "$TMP/repair-result.html"'''
if s.count(old)!=1:
    raise SystemExit(f'repair driver anchor count={s.count(old)}')
p.write_text(s.replace(old,new,1),encoding='utf-8')
print('P02_REPAIR_DRIVER_PATCH=PASS')
